mapper.select:
SELECT t.*, c.name AS campaign_name, g.name AS ad_group_name
FROM ecom_ad_target t
JOIN ecom_ad_campaign c ON c.id = t.campaign_id
JOIN ecom_ad_group g ON g.id = t.ad_group_id

    t.campaign_id = #{campaignId}
    AND t.ad_group_id = #{adGroupId}
    AND t.status = #{status}
    AND t.target_type = #{targetType}
    AND t.target_text LIKE CONCAT('%', #{keyword}, '%')

ORDER BY t.ad_group_id, t.target_type, t.target_text

SELECT 'TARGET' AS level, t.id, t.store_id, s.name AS store_name, s.currency, t.campaign_id, c.name AS campaign_name, c.tags AS campaign_tags, c.ad_type, t.ad_group_id, t.target_text AS name, t.status, t.platform_target_id AS platform_id, t.target_type, t.bid, t.base_bid, t.schedule_factor FROM ecom_ad_target t JOIN ecom_ad_campaign c ON c.id = t.campaign_id JOIN ecom_ad_group g ON g.id = t.ad_group_id JOIN ecom_store s ON s.id = t.store_id WHERE t.target_type <> 'NEGATIVE' AND t.status <> 'ARCHIVED' AND g.status <> 'ARCHIVED' AND c.status <> 'ARCHIVED'
AND t.store_id IN #{i}
AND t.campaign_id = #{campaignId} AND t.ad_group_id = #{adGroupId} AND c.ad_type = #{adType} AND c.name LIKE CONCAT('%', #{keyword}, '%') ORDER BY t.store_id, c.name, t.ad_group_id, t.target_text
